const CACHE='ssc-compass-shell-v19-inline-textbooks';
const FILES=['./','./index.html','./privacy.html','./terms.html','./style.css','./app.js','./core.js','./schedule.js','./upcoming-tests.js','./reminders.js','./syllabus.js','./textbooks.js','./textbook-reader.js','./quiz-config.js','./result-tools.js','./study-tools.js','./cloud.js','./firebase-config.js','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('ssc-compass-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin||new URL(e.request.url).pathname.startsWith('/api/'))return;e.respondWith(fetch(e.request,{cache:'no-cache'}).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
self.addEventListener('notificationclick',e=>{e.notification.close();e.waitUntil((async()=>{const tabs=await clients.matchAll({type:'window',includeUncontrolled:true});const match=tabs.find(c=>c.url.startsWith(self.registration.scope));if(match)return match.focus();return clients.openWindow('./')})());});
